fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    // Compute the ceiling of health / strength:
    // (health + strength - 1) / strength, all performed in i64 to avoid overflow.
    let h = health as i64;
    let s = strength as i64;
    (h + s - 1) / s
}

fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    // Takahashi needs this many turns to defeat Aoki:
    let takahashi_turns = exec_turns_to_defeat(c, b);
    // Aoki needs this many turns to defeat Takahashi:
    let aoki_turns = exec_turns_to_defeat(a, d);

    // Because Takahashi attacks first, he wins if he can defeat Aoki
    // in no more turns than Aoki needs to defeat him.
    if takahashi_turns <= aoki_turns {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}

